function setupCanvas(id){const el=$(id),r={width:el.clientWidth,height:el.clientHeight};if(r.width<2||r.height<2)return null;const dpr=Math.min(devicePixelRatio,2),w=Math.floor(r.width*dpr),h=Math.floor(r.height*dpr);if(el.width!==w||el.height!==h){el.width=w;el.height=h;}const ctx=el.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,r.width,r.height);return {ctx,w:r.width,h:r.height};}
function orbitBackdrop(ctx,w,h,radius){const x=w/2,y=h/2;ctx.save();ctx.strokeStyle='#718e8c10';ctx.lineWidth=1;for(let gx=0;gx<w;gx+=35){ctx.beginPath();ctx.moveTo(gx,0);ctx.lineTo(gx,h);ctx.stroke();}for(let gy=0;gy<h;gy+=35){ctx.beginPath();ctx.moveTo(0,gy);ctx.lineTo(w,gy);ctx.stroke();}ctx.translate(x,y);ctx.strokeStyle='#9bb7ad2a';ctx.setLineDash([2,6]);ctx.beginPath();ctx.moveTo(-w/2,0);ctx.lineTo(w/2,0);ctx.stroke();ctx.setLineDash([]);const grad=ctx.createRadialGradient(-radius*.3,-radius*.35,5,0,0,radius);grad.addColorStop(0,'#ac9476');grad.addColorStop(.55,'#796c5c');grad.addColorStop(1,'#343a38');ctx.fillStyle=grad;ctx.beginPath();ctx.arc(0,0,radius,0,TAU);ctx.fill();ctx.strokeStyle='#cbb49922';for(let i=0;i<9;i++){const a=i*.7+1;ctx.beginPath();ctx.ellipse(Math.cos(a)*radius*.45,Math.sin(a)*radius*.45,radius*.2,radius*.08,a,0,TAU);ctx.stroke();}ctx.strokeStyle='#9db5ac38';ctx.beginPath();ctx.arc(0,0,radius+2,0,TAU);ctx.stroke();ctx.fillStyle='#f1f8edb0';ctx.font='11px Segoe UI';ctx.textAlign='center';ctx.fillText('REFERENCE PLANET',0,3);ctx.restore();}

