 ctx.strokeStyle=g.elevation>=10?'#c18a43':'#ba8880';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(tx,ty);ctx.stroke();ctx.fillStyle='#278a7d';ctx.beginPath();ctx.arc(sx,sy,4,0,TAU);ctx.fill();ctx.fillStyle='#244f65';ctx.fillRect(tx-4,ty-5,8,10);ctx.fillStyle='#357d96';ctx.fillRect(tx-13,ty-3,7,6);ctx.fillRect(tx+6,ty-3,7,6);
