function advanceTransfer(now){if(rehearsal){rehearsal.t=(now-rehearsal.started)/1000;const phase=rehearsal.t<rehearsal.burnDuration?0:rehearsal.t>rehearsal.duration-rehearsal.burnDuration?2:1;updateProgress(phase);$('burnDirection').textContent=['1 · Burn against travel','2 · Coast with engines off','3 · Match the new orbit'][phase];$('burnExplanation').textContent=['The speed change lowers the far side of the orbit.','Gravity carries the ship inward and increases its speed.','The second speed change makes the lower orbit circular.'][phase];$('orbitPhase').textContent=phase===0?'DEPARTURE BURN':phase===1?'COAST · ACCELERATED PLAYBACK':'CIRCULARIZATION BURN';if(rehearsal.t>=rehearsal.duration){const task=orbitTask();record.completed.orbit=task.budget&&task.inspection;save();rehearsal=null;$('orbitOutcome').className='feedback '+(record.completed.orbit?'good':'bad');$('orbitOutcome').textContent=record.completed.orbit?`Plan accepted: ${task.detail.toFixed(1)}× image scale for ${plan.totalDv.toFixed(1)} m/s. Next, build a relay for this orbit.`:!task.budget?'Closer is not always better: this plan exceeds the 170 m/s budget. Try a slightly higher orbit.':'This orbit is too high for the inspection. Try a lower altitude for at least 1.8× image scale.';$('orbitPhase').textContent='TRANSFER REHEARSED';$('runTransfer').disabled=false;$('runTransfer').textContent=record.completed.orbit?'Continue to relay →':'Try another orbit →';updateProgress(3);ping(1100);toast(record.completed.orbit?'Inspection orbit accepted. Build your relay next.':'Transfer flown. Review the mission tradeoff.');}}}
